mapper.select:
WITH filtered_data AS ( SELECT *, count(*) OVER() AS total_count FROM t_ds_process_instance WHERE coalesce(schedule_time, start_time) >= TO_TIMESTAMP(#{startTime}, 'YYYY-MM-DD HH24:MI:SS') AND coalesce(schedule_time, start_time) <= TO_TIMESTAMP(#{endTime}, 'YYYY-MM-DD HH24:MI:SS')
AND state = #{status}
AND project_code IN
#{item}
) SELECT #{currentPage} AS current_page, #{pageSize} AS page_size, (SELECT total_count FROM filtered_data LIMIT 1) AS total_count, (SELECT ceil(total_count::float / #{pageSize}) FROM filtered_data LIMIT 1) AS total_pages, array_to_json(array_agg(row_to_json(t))) AS data FROM ( SELECT * FROM filtered_data LIMIT #{pageSize} OFFSET (#{currentPage} - 1) * #{pageSize} ) t
